                                        self.scores[t_or_d]['fn'])

def get_auth_header(self):
        """
        Getting the authorization header according to the authentication procedure

        :return [dict]: Authorization header
        """
        if self.api.is_authenticated:
            return {"Authorization": "Bearer %s" % self.api.access_token}
        return {"Authorization": "Client-ID %s" % self.api.client_id}

def get_auth_header(self):
        """
        Getting the authorization header according to the authentication procedure

        :return [dict]: Authorization header
        """
        if self.auth_type == 'basic':
            return {'Authorization': 'Basic ' + self.auth_token}
        elif self.auth_type == 'token':
            return {'Authorization': 'Bearer ' + self.auth_token}
        elif self.auth_type == 'api_key':
            return {'X-API-KEY': self.auth_token}
        else:
            return {}

def send_slack_message(message):
    """Send a message to the slack channel #coretools"""

    if 'SLACK_WEB_HOOK' not in os.environ:
        raise EnvironmentError("Could not find SLACK_WEB_HOOK environment variable")

    webhook = os.environ['SLACK_WEB_HOOK']

    r = requests.post(webhook, json={'text':message, 'username': 'Release Bot'})
    if r.status_code != 200:
        raise RuntimeError("Could not post message to slack channel")

