def _sample_as_dict(self, sample):
        """Convert list-like ``sample`` (list/dict/dimod.SampleView),
        ``list: var``, to ``map: idx -> var``.
        """
        if isinstance(sample, dict):
            return sample
        if isinstance(sample, (list, numpy.ndarray)):
            sample = enumerate(sample)
        return dict(sample)

def _sample_as_dict(self, sample):
        """Convert list-like ``sample`` (list/dict/dimod.SampleView),
        ``list: var``, to ``map: idx -> var``.
        """
        if isinstance(sample, dict):
            return sample
        elif isinstance(sample, list):
            return {idx: v for idx, v in enumerate(sample)}
        elif isinstance(sample, dimod.SampleView):
            return sample.to_dict()
        else:
            raise TypeError("sample must be a list, dict, or dimod.SampleView")

