def utf8(value):
    r"""
    Check that the string is UTF-8. Returns an encode bytestring.

    >>> utf8(b'\xe0')  # doctest: +ELLIPSIS
    Traceback (most recent call last):
    ...
    ValueError: Not UTF-8: ...
    """
    try:
        if isinstance(value, bytes):
            return value.decode('utf-8')
        else:
            return value
    except Exception:
        raise ValueError('Not UTF-8: %r' % value)

def get_object_cache_keys(instance):
    """
    Return the cache keys associated with an object.
    """
    if instance.pk is None or instance._state.adding:
        return []

    keys = []
    tr_models = instance._parler_meta.get_all_models()

    # TODO: performs a query to fetch the language codes. Store that in memcached too.
    for language in instance.get_available_languages():
        for tr_model in tr_models:
            keys.append(get_translation_cache_key(tr_model, instance.pk, language))

    return keys

def get_object_cache_keys(instance):
    """
    Return the cache keys associated with an object.
    """
    return [
        get_object_cache_key(instance, field)
        for field in instance._meta.get_fields()
        if field.get_internal_type() in ('ForeignKey', 'OneToOneField')
    ]

def apply_vcc(self,vcc):
        """
        Applies velocity contrast curve constraint to each population

        See :func:`vespa.stars.StarPopulation.apply_vcc`;
        all arguments passed to that function for each population.

        """
        if 'secondary spectrum' not in self.constraints:
            self.constraints.append('secondary spectrum')
        for pop in self.poplist:
            if not pop.is_specific:
                try:
                    pop.apply_vcc(vcc)
                except:
                    logging.info('VCC constraint not applied to %s model' % (pop.model))

def apply_vcc(self,vcc):
        """
        Applies velocity contrast curve constraint to each population

        See :func:`vespa.stars.StarPopulation.apply_vcc`;
        all arguments passed to that function for each population.

        """
        for pop in self.populations:
            pop.apply_vcc(vcc)

def create_label(self, name, color):
        """Create a label for this repository.

        :param str name: (required), name to give to the label
        :param str color: (required), value of the color to assign to the
            label, e.g., '#fafafa' or 'fafafa' (the latter is what is sent)
        :returns: :class:`Label <github3.issues.label.Label>` if successful,
            else None
        """
        if not name:
            raise ValueError("name is required")
        if not color:
            raise ValueError("color is required")
        if not isinstance(color, str):
            raise ValueError("color must be a string")
        if color[0] == "#":
            color = color[1:]
        data = {"name": name, "color": color}
        url = self._url + "/labels"
        return self._requester.post(url, data=data)

def changed(self, node=None, allowcache=False):
        """
        Returns if the node is up-to-date with respect to the BuildInfo
        stored last time it was built.

        For File nodes this is basically a wrapper around Node.changed(),
        but we allow the return value to get cached after the reference
        to the Executor got released in release_target_info().

        @see: Node.changed()
        """
        if node is None:
            try:
                return self._memo['changed']
            except KeyError:
                pass

        has_changed = SCons.Node.Node.changed(self, node)
        if allowcache:
            self._memo['changed'] = has_changed
        return has_changed

def save_data(fpath, data, **kwargs):
    """ More generic interface to write data """
    ext = splitext(fpath)[1]
    if ext in ['.pickle', '.cPkl', '.pkl']:
        return save_cPkl(fpath, data, **kwargs)
    elif ext in ['.json']:
        return save_json(fpath, data, **kwargs)
    elif ext in ['.hdf5']:
        return save_hdf5(fpath, data, **kwargs)
    elif ext in ['.txt']:
        return save_text(fpath, **kwargs)
    elif HAS_NUMPY and ext in ['.npz', '.npy']:
        return save_numpy(fpath, data, **kwargs)
    else:
        assert False, 'unknown ext=%r for fpath=%r' % (ext, fpath)

def save_data(fpath, data, **kwargs):
    """ More generic interface to write data """
    if fpath.endswith('.h5'):
        save_h5(fpath, data, **kwargs)
    elif fpath.endswith('.npz'):
        save_npz(fpath, data, **kwargs)
    elif fpath.endswith('.json'):
        save_json(fpath, data, **kwargs)
    elif fpath.endswith('.pkl'):
        save_pkl(fpath, data, **kwargs)
    else:
        raise ValueError('Unknown file extension')

def login(self, password):
        """Attempts to log in as the current user with given password"""

        if self.logged_in:
            raise RuntimeError("User already logged in!")

        params = {"name": self.nick, "password": password}
        resp = self.conn.make_api_call("login", params)
        if "error" in resp:
            raise RuntimeError(
                f"Login failed: {resp['error'].get('message') or resp['error']}"
            )
        self.session = resp["session"]
        self.conn.make_call("useSession", self.session)
        self.conn.cookies.update({"session": self.session})
        self.logged_in = True
        return True

def view_interactively(self, backend='wx'):
        """Loads the current sample in a graphical interface for drawing gates.

        Parameters
        ----------
        backend: 'auto' | 'wx' | 'webagg'
            Specifies which backend should be used to view the sample.
        """
        if backend == 'auto':
            if matplotlib.__version__ >= '1.4.3':
                backend = 'WebAgg'
            else:
                backend = 'wx'

        if backend == 'wx':
            from FlowCytometryTools.gui.wx_backend import gui
        elif backend == 'webagg':
            from FlowCytometryTools.gui.webagg_backend import gui
        else:
            raise ValueError('No support for backend {}'.format(backend))

        gui.GUILauncher(measurement=self)

def closeView(self, view=None):
        """
        Closes the inputed view.

        :param      view | <int> || <XView> || None
        """
        if type(view) == int:
            view = self.widget(view)
        elif view == None:
            view = self.currentView()

        index = self.indexOf(view)
        if index == -1:
            return False

        # close the view
        count = self.count()
        if count == 1:
            self.closePanel()
        else:
            view.close()

        return True

def closeView(self, view=None):
        """
        Closes the inputed view.

        :param      view | <int> || <XView> || None
        """
        if view is None:
            self.close()
        elif isinstance(view, int):
            self.close(view)
        elif isinstance(view, XView):
            self.close(view.id)
        else:
            raise TypeError("View must be an integer, XView, or None.")

def prepare(self):
        """Check that the file exists, optionally downloads it.
        Checks that the file is indeed an SQLite3 database.
        Optionally check the MD5."""
        if not os.path.exists(self.path):
            if self.retrieve:
                print("Downloading SQLite3 database...")
                download_from_url(self.retrieve, self.path, progress=True)
            else: raise Exception("The file '" + self.path + "' does not exist.")
        self.check_format()
        if self.known_md5: assert self.known_md5 == self.md5
        self.prepared = True

def prepare(self):
        """Check that the file exists, optionally downloads it.
        Checks that the file is indeed an SQLite3 database.
        Optionally check the MD5."""
        if not os.path.exists(self.filename):
            if self.url is None:
                raise IOError("File %s does not exist" % self.filename)
            else:
                self.download()
        if not os.path.exists(self.filename):
            raise IOError("File %s does not exist" % self.filename)
        if self.check_md5:
            self.check_md5()
        if not self.is_sqlite3():
            raise IOError("File %s is not a SQLite3 database" % self.filename)

def scrypt_mcf_check(scrypt, mcf, password):
    """Returns True if the password matches the given MCF hash

    Supports both the libscrypt $s1$ format and the $7$ format.
    """
    if not isinstance(mcf, bytes):
        raise TypeError('MCF must be a byte string')
    if isinstance(password, unicode):
        password = password.encode('utf8')
    elif not isinstance(password, bytes):
        raise TypeError('password must be a unicode or byte string')

    N, r, p, salt, hash, hlen = _scrypt_mcf_decode(mcf)
    h = scrypt(password, salt, N=N, r=r, p=p, olen=hlen)
    cmp = 0
    for i, j in zip(bytearray(h), bytearray(hash)):
        cmp |= i ^ j
    return cmp == 0

def scrypt_mcf_check(scrypt, mcf, password):
    """Returns True if the password matches the given MCF hash

    Supports both the libscrypt $s1$ format and the $7$ format.
    """
    if mcf.startswith('$s1$'):
        return scrypt.check(password, mcf)
    elif mcf.startswith('$7$'):
        return scrypt.check(password, mcf)
    else:
        raise ValueError('Invalid MCF hash')

def _normalize_sort_SQL(self, field_name, field_vals, sort_dir_str):
        """
        allow sorting by a set of values

        http://stackoverflow.com/questions/3303851/sqlite-and-custom-order-by
        """
        if sort_dir_str == 'desc':
            sort_dir_str = 'desc'
        else:
            sort_dir_str = 'asc'

        if field_name == 'id':
            field_name = 'id'
        else:
            field_name = 'name'

        if field_vals == 'all':
            field_vals = 'all'
        else:
            field_vals = '(' + ','.join(field_vals) + ')'

        return ' '.join([field_name, field_vals, sort_dir_str])

def _check_for_default_values(fname, arg_val_dict, compat_args):
    """
    Check that the keys in `arg_val_dict` are mapped to their
    default values as specified in `compat_args`.

    Note that this function is to be called only when it has been
    checked that arg_val_dict.keys() is a subset of compat_args

    """
    for arg in compat_args:
        if arg in arg_val_dict:
            if arg_val_dict[arg] == compat_args[arg]['default']:
                continue
            else:
                raise ValueError(
                    "The value of argument '%s' in function '%s' is not "
                    "compatible with the default value '%s'." %
                    (arg, fname, compat_args[arg]['default']))

def start(name, call=None):
    """
    Start a node.

    CLI Example:

    .. code-block:: bash

        salt-cloud -a start mymachine
    """
    if call != 'action':
        raise SaltCloudSystemExit(
            'The show_instance action must be called with -a or --action.'
        )

    data = query(action='ve', command='{0}/start'.format(name), method='PUT')

    if 'error' in data:
        return data['error']

    return {'Started': '{0} was started.'.format(name)}

def start(name, call=None):
    """
    Start a node.

    CLI Example:

    .. code-block:: bash

        salt-cloud -a start mymachine
    """
    if call != "action":
        raise SaltCloudSystemExit(
            "The start action must be called with -a or --action."
        )

    node = _get_node(name)
    if node is None:
        raise SaltCloudSystemExit("No node found with the name {}".format(name))

    if node["state"] == "running":
        log.info("Node %s is already running", name)
        return {"node": name, "action": "start", "result": True, "comment": ""}

    if node["state"] == "stopped":
        log.info("Starting node %s", name)
        try:
            node.start()
        except SaltCloudSystemExit as exc:
            return {"node": name, "action": "start", "result": False, "comment": str(exc)}
        return {"node": name, "action": "start", "result": True, "comment": ""}

    log.info("Node %s is not running or stopped", name)
    return {"node": name, "action": "start", "result": False, "comment": ""}

def _configure_context(ctx, opts, skip=()):
        """
        Configures context of public key operations
        @param ctx - context to configure
        @param opts - dictionary of options (from kwargs of calling
            function)
        @param skip - list of options which shouldn't be passed to
            context
        """

        for oper in opts:
            if oper in skip:
                continue
            if isinstance(oper,chartype):
                op = oper.encode("ascii")
            else:
                op = oper
            if isinstance(opts[oper],chartype):
                value = opts[oper].encode("ascii")
            elif isinstance(opts[oper],bintype):
                value = opts[oper]
            else:
                if pyver == 2:
                    value = str(opts[oper])
                else:
                    value = str(opts[oper]).encode('ascii')
            ret = libcrypto.EVP_PKEY_CTX_ctrl_str(ctx, op, value)
            if ret == -2:
                raise PKeyError("Parameter %s is not supported by key" % oper)
            if ret < 1:
                raise PKeyError("Error setting parameter %s" % oper)

def _configure_context(ctx, opts, skip=()):
        """
        Configures context of public key operations
        @param ctx - context to configure
        @param opts - dictionary of options (from kwargs of calling
            function)
        @param skip - list of options which shouldn't be passed to
            context
        """
        for k, v in opts.items():
            if k not in skip:
                ctx.set_option(k, v)

def build_condition(filter_map, using=CONDITIONS):
    """ Implement the conditions described in
    docs.aws.amazon.com/amazondynamodb/latest/APIReference/API_Condition.html

    """
    if not filter_map:
        return

    filters = {}
    dynamizer = Dynamizer()

    for field_and_op, value in filter_map.items():
        field_bits = field_and_op.split('__')
        fieldname = '__'.join(field_bits[:-1])

        try:
            op = using[field_bits[-1]]
        except KeyError:
            raise ConditionNotRecognizedException(
                "Operator '%s' from '%s' is not recognized." % (
                    field_bits[-1],
                    field_and_op
                )
            )

        lookup = {
            'AttributeValueList': [],
            'ComparisonOperator': op,
        }

        # Special-case the ``NULL/NOT_NULL`` case.
        if field_bits[-1] == 'null':
            del lookup['AttributeValueList']

            if value is False:
                lookup['ComparisonOperator'] = 'NOT_NULL'
            else:
                lookup['ComparisonOperator'] = 'NULL'
        # Special-case the ``BETWEEN`` case.
        elif field_bits[-1] == 'between':
            if len(value) == 2 and isinstance(value, (list, tuple)):
                lookup['AttributeValueList'].append(
                    dynamizer.encode(value[0])
                )
                lookup['AttributeValueList'].append(
                    dynamizer.encode(value[1])
                )
        # Special-case the ``IN`` case
        elif field_bits[-1] == 'in':
            for val in value:
                lookup['AttributeValueList'].append(dynamizer.encode(val))
        else:
            # Fix up the value for encoding, because it was built to only work
            # with ``set``s.
            if isinstance(value, (list, tuple)):
                value = set(value)
            lookup['AttributeValueList'].append(
                dynamizer.encode(value)
            )

        # Finally, insert it into the filters.
        filters[fieldname] = lookup
    return filters

def build_condition(filter_map, using=CONDITIONS):
    """ Implement the conditions described in
    docs.aws.amazon.com/amazondynamodb/latest/APIReference/API_Condition.html

    """
    conditions = []
    for key, value in filter_map.items():
        if key in using:
            conditions.append(using[key](key, value))
        else:
            raise ValueError("Unknown condition: %s" % key)
    return " AND ".join(conditions)

def load_from_dict(self, data: dict, overwrite: bool=True):
        """
        Loads key/values from dicts or list into the ConfigKey.
        :param data: The data object to load.
                        This can be a dict, or a list of key/value tuples.
        :param overwrite: Should the ConfigKey overwrite data already in it?
        """
        if isinstance(data, dict):
            for key, value in data.items():
                self.set(key, value, overwrite)
        elif isinstance(data, list):
            for key, value in data:
                self.set(key, value, overwrite)
        else:
            raise TypeError("Data must be a dict or a list of key/value tuples.")

def _plot_time_list(sdat, lovs, tseries, metas, times=None):
    """Plot requested profiles"""
    if times is None:
        times = {}
    for vfig in lovs:
        fig, axes = plt.subplots(nrows=len(vfig), sharex=True,
                                 figsize=(12, 2 * len(vfig)))
        axes = [axes] if len(vfig) == 1 else axes
        fname = ['time']
        for iplt, vplt in enumerate(vfig):
            ylabel = None
            for ivar, tvar in enumerate(vplt):
                fname.append(tvar)
                time = times[tvar] if tvar in times else tseries['t']
                axes[iplt].plot(time, tseries[tvar],
                                conf.time.style,
                                label=metas[tvar].description)
                lbl = metas[tvar].kind
                if ylabel is None:
                    ylabel = lbl
                elif ylabel != lbl:
                    ylabel = ''
            if ivar == 0:
                ylabel = metas[tvar].description
            if ylabel:
                _, unit = sdat.scale(1, metas[tvar].dim)
                if unit:
                    ylabel += ' ({})'.format(unit)
                axes[iplt].set_ylabel(ylabel)
            if vplt[0][:3] == 'eta':  # list of log variables
                axes[iplt].set_yscale('log')
            axes[iplt].set_ylim(bottom=conf.plot.vmin, top=conf.plot.vmax)
            if ivar:
                axes[iplt].legend()
            axes[iplt].tick_params()
        _, unit = sdat.scale(1, 's')
        if unit:
            unit = ' ({})'.format(unit)
        axes[-1].set_xlabel('Time' + unit)
        axes[-1].set_xlim((tseries['t'].iloc[0], tseries['t'].iloc[-1]))
        axes[-1].tick_params()
        misc.saveplot(fig, '_'.join(fname))

def wrap(self, value, timestamp=None):
        """Pack python value into Value
        """
        if timestamp is None:
            timestamp = time.time()
        return Value(value, timestamp)

def parse_input(args, kwargs=None, condition=True, no_parse=None):
    """
    Parse out the args and kwargs from a list of input values. Optionally,
    return the args and kwargs without passing them to condition_input().

    Don't pull args with key=val apart if it has a newline in it.
    """
    if no_parse is None:
        no_parse = ()
    if kwargs is None:
        kwargs = {}
    _args = []
    _kwargs = {}
    for arg in args:
        if isinstance(arg, six.string_types):
            arg_name, arg_value = parse_kwarg(arg)
            if arg_name:
                _kwargs[arg_name] = yamlify_arg(arg_value) \
                    if arg_name not in no_parse \
                    else arg_value
            else:
                _args.append(yamlify_arg(arg))
        elif isinstance(arg, dict):
            # Yes, we're popping this key off and adding it back if
            # condition_input is called below, but this is the only way to
            # gracefully handle both CLI and API input.
            if arg.pop('__kwarg__', False) is True:
                _kwargs.update(arg)
            else:
                _args.append(arg)
        else:
            _args.append(arg)
    _kwargs.update(kwargs)
    if condition:
        return condition_input(_args, _kwargs)
    return _args, _kwargs

def parse_input(args, kwargs=None, condition=True, no_parse=None):
    """
    Parse out the args and kwargs from a list of input values. Optionally,
    return the args and kwargs without passing them to condition_input().

    Don't pull args with key=val apart if it has a newline in it.
    """
    if no_parse is None:
        no_parse = []
    if kwargs is None:
        kwargs = {}
    args = []
    for arg in args:
        if arg in no_parse:
            args.append(arg)
        elif '=' in arg:
            arg_split = arg.split('=', 1)
            args.append(arg_split[0])
            kwargs[arg_split[0]] = arg_split[1]
        else:
            args.append(arg)
    if condition:
        condition_input(args, kwargs)
    return args, kwargs

def in_book_search_highlighted_results(request):
    """In-book search - returns a highlighted version of the HTML."""
    if request.method == 'POST':
        form = InBookSearchForm(request.POST)
        if form.is_valid():
            search_term = form.cleaned_data['search_term']
            search_results = search_in_book(search_term)
            return render(request, 'search/in_book_search_highlighted_results.html',
                          {'search_results': search_results, 'search_term': search_term})
    else:
        form = InBookSearchForm()
    return render(request, 'search/in_book_search.html', {'form': form})
